import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';

import { hash } from '../lib/contracts.mjs';
import {
  canonicalizeProtectedHeaders, classifyHealthcheckRuntime, fetchImmutableConfigBlob, parseAnonymousBearerChallenge, parseApprovedSourceReference, projectConfigBlobRedirect, resolveRegistryDigest,
  parseRegistryTokenResponse, platformCompatible, projectIndexPlatformDescriptors, projectProtectedResponseHeaders,
  selectCompatiblePlatform, validateRegistryResolverContract, validateResponseCookieNonParticipation,
} from '../lib/registry-digest-resolver.mjs';

const load = () => JSON.parse(fs.readFileSync(new URL('../contracts/registry-digest-resolver-contract.json', import.meta.url), 'utf8'));
const clone = structuredClone;
const H = character => character.repeat(64);
const digest = bytes => `sha256:${hash(bytes)}`;
const json = value => Buffer.from(JSON.stringify(value), 'utf8');
const code = expected => error => error?.code === expected;
const platform = { os: 'linux', architecture: 'arm64', variant: 'v8' };
const source = () => load().approved_sources.find(row => row.role === 'AUTH');
const raw = (...pairs) => pairs.flat();
const challenge = ({ realm='https://auth.docker.io/token', service='registry.docker.io', scope='repository:supabase/gotrue:pull', separator=',' }={}) => `Bearer realm="${realm}"${separator}service="${service}"${separator}scope="${scope}"`;
const tokenPath = '/token?service=registry.docker.io&scope=repository%3Asupabase%2Fgotrue%3Apull';
const cookieContext = (responseCookie, overrides={}) => ({ contract:load(), host:'auth.docker.io', path:tokenPath, purpose:'ANONYMOUS_TOKEN', requestHeaders:{accept:'application/json'}, cookieJar:'FORBIDDEN', responseStatusCode:200, responseCookie, ...overrides });
const select = index => selectCompatiblePlatform(index, load());

function response(bytes, type, digestValue = digest(bytes), status = 200, extra = {}) {
  return { status, headers: { 'content-type': type, 'docker-content-digest': digestValue, ...extra }, body: bytes };
}

function artifacts({ indexType = 'application/vnd.oci.image.index.v1+json', manifestType = 'application/vnd.oci.image.manifest.v1+json', descriptors = null, configValue = null } = {}) {
  const contract = load();
  const config = configValue ?? { architecture: 'arm64', os: 'linux', config: { User: '1000', WorkingDir: '/work', Entrypoint: ['/entrypoint'], Cmd: ['serve'], Volumes: { '/data': {} }, ExposedPorts: { '9999/tcp': {} }, Healthcheck: { Test: ['CMD','check'], Interval: 1000000, Timeout: 1000000, Retries: 1, StartPeriod: 0 } } };
  const configBytes = json(config), configDigest = digest(configBytes);
  const child = { schemaVersion: 2, mediaType: manifestType, config: { mediaType: contract.media_types.configs[0], size: configBytes.length, digest: configDigest }, layers: [{ mediaType: 'application/vnd.oci.image.layer.v1.tar+gzip', size: 1, digest: `sha256:${H('9')}` }] };
  const childBytes = json(child), childDigest = digest(childBytes);
  const manifestRows = descriptors ?? [{ mediaType: manifestType, size: childBytes.length, digest: childDigest, platform: clone(platform) }];
  const index = { schemaVersion: 2, mediaType: indexType, manifests: manifestRows };
  const indexBytes = json(index);
  return { contract, config, configBytes, configDigest, child, childBytes, childDigest, index, indexBytes,
    indexResponse: response(indexBytes,indexType), childResponse: response(childBytes,manifestType), configResponse: { status:200,headers:{'content-type':'application/octet-stream'},body:configBytes } };
}

function anonymousQueue(a = artifacts()) {
  const challenge = `Bearer realm="https://auth.docker.io/token",service="registry.docker.io",scope="repository:supabase/gotrue:pull"`;
  return [
    { status:401,headers:{'www-authenticate':challenge},body:Buffer.from('unauthorized') },
    { status:200,headers:{'content-type':'application/json'},body:json({token:'safe.synthetic.token'}) },
    a.indexResponse, a.childResponse, a.configResponse,
  ];
}

const redirectLocation = 'https://cdn.example.test/registry/blobs/config?X-Signature=secret-value&X-Expires=60';
function redirectedQueue(a = artifacts(), location = redirectLocation, status = 307) {
  const queue = anonymousQueue(a);
  queue[4] = { status, headers: { location }, body: Buffer.alloc(0) };
  queue.push(a.configResponse);
  return queue;
}

function redirectProjection(overrides = {}) {
  const contract = load(), approvedSource = source(), requestedDigest = `sha256:${H('a')}`;
  return projectConfigBlobRedirect({ contract, source: approvedSource, requestedDigest,
    sourcePath: `/v2/${approvedSource.repository}/blobs/${requestedDigest}`,
    response: { status: 307, headers: { location: redirectLocation }, body: Buffer.alloc(0) }, ...overrides });
}

function replaceConfigBytes(a, bytes) {
  a.configBytes = bytes; a.configDigest = digest(bytes);
  a.child.config.size = bytes.length; a.child.config.digest = a.configDigest;
  a.childBytes = json(a.child); a.childDigest = digest(a.childBytes);
  a.index.manifests[0].size = a.childBytes.length; a.index.manifests[0].digest = a.childDigest;
  a.indexBytes = json(a.index);
  a.indexResponse = response(a.indexBytes, a.index.mediaType);
  a.childResponse = response(a.childBytes, a.child.mediaType);
  a.configResponse = { status: 200, headers: { 'content-type': 'application/octet-stream' }, body: bytes };
  return a;
}

async function fetchConfigWith(a, responses, overrides = {}) {
  const calls = [], queue = [...responses];
  const request = async spec => { calls.push(clone(spec)); assert.ok(queue.length > 0); return queue.shift(); };
  const result = await fetchImmutableConfigBlob({ contract: load(), source: source(), configDescriptor: a.child.config,
    layerDigests: a.child.layers.map(layer => layer.digest), requestedDigest: a.child.config.digest,
    authorization: 'Bearer safe.synthetic.token', request, ...overrides });
  return { result, calls };
}

async function resolveWith(queue, contract = load()) {
  const calls = [];
  const request = async spec => { calls.push(clone(spec)); assert.ok(queue.length > 0); return queue.shift(); };
  const result = await resolveRegistryDigest({ contract, role:'AUTH', sourceReference:'supabase/gotrue:v2.195.0', request, resolverSha256:H('a'), clock:()=>new Date('2000-01-01T00:00:00.000Z') });
  return { result, calls };
}

async function resolveHealthcheck(healthcheck) {
  const config = { architecture: 'arm64', os: 'linux', config: {} };
  if (healthcheck !== undefined) config.config.Healthcheck = healthcheck;
  const a = artifacts({ configValue: config });
  return resolveWith(anonymousQueue(a));
}

test('resolver contract is strict and fixed to public Docker Hub metadata', () => assert.equal(validateRegistryResolverContract(load()).resolver_id,'WINWIN_PUBLIC_REGISTRY_METADATA_V1'));
test('no Healthcheck projects as absent and non-executing', async () => { const {result}=await resolveHealthcheck(undefined); assert.equal(result.healthcheck.state,'ABSENT'); assert.equal(result.healthcheck.executable,false); });
test('Healthcheck NONE projects as disabled while retaining bounded timing evidence', async () => { const {result}=await resolveHealthcheck({Test:['NONE'],Interval:1000000}); assert.equal(result.healthcheck.state,'DISABLED'); assert.equal(result.healthcheck.test_form,'NONE'); assert.deepEqual(result.healthcheck.interval,{present:true,value_nanoseconds:1000000}); });
test('Healthcheck CMD records only bounded argv structure and payload hash', async () => { const {result}=await resolveHealthcheck({Test:['CMD','/bin/check','--ready']}); assert.equal(result.healthcheck.test_form,'CMD'); assert.equal(result.healthcheck.argv_element_count,2); assert.equal(result.healthcheck.payload_byte_length,24); assert.doesNotMatch(JSON.stringify(result),/\/bin\/check|--ready/); });
test('Healthcheck CMD-SHELL records only bounded shell payload structure and hash', async () => { const {result}=await resolveHealthcheck({Test:['CMD-SHELL','check || exit 1']}); assert.equal(result.healthcheck.test_form,'CMD-SHELL'); assert.equal(result.healthcheck.argv_element_count,null); assert.doesNotMatch(JSON.stringify(result),/check \|\| exit 1/); });
test('malformed Healthcheck Test is rejected', async () => await assert.rejects(()=>resolveHealthcheck({Test:'CMD'}),code('REGISTRY_CONFIG_HEALTHCHECK_TEST')));
test('empty Healthcheck Test is rejected', async () => await assert.rejects(()=>resolveHealthcheck({Test:[]}),code('REGISTRY_CONFIG_HEALTHCHECK_TEST')));
test('unknown Healthcheck Test form is rejected', async () => await assert.rejects(()=>resolveHealthcheck({Test:['OTHER','check']}),code('REGISTRY_CONFIG_HEALTHCHECK_TEST_FORM')));
test('unknown Healthcheck key is rejected', async () => await assert.rejects(()=>resolveHealthcheck({Test:['CMD','check'],Unknown:1}),code('REGISTRY_CONFIG_HEALTHCHECK')));
test('Healthcheck timing fields retain independent presence and nanosecond values', async () => { const {result}=await resolveHealthcheck({Test:['CMD','check'],Interval:1000000,Timeout:2000000,StartPeriod:0,StartInterval:3000000}); const h=result.healthcheck; assert.deepEqual([h.interval,h.timeout,h.start_period,h.start_interval],[{present:true,value_nanoseconds:1000000},{present:true,value_nanoseconds:2000000},{present:true,value_nanoseconds:0},{present:true,value_nanoseconds:3000000}]); });
test('Healthcheck Retries retains independent presence and value', async () => { const {result}=await resolveHealthcheck({Test:['CMD','check'],Retries:4}); assert.deepEqual(result.healthcheck.retries,{present:true,value:4}); });
for (const timing of [-1,1,1.5]) test(`invalid Healthcheck timing ${timing} is rejected`, async () => await assert.rejects(()=>resolveHealthcheck({Test:['CMD','check'],Interval:timing}),code('REGISTRY_CONFIG_HEALTHCHECK_VALUE')));
for (const retries of [-1,1.5]) test(`invalid Healthcheck retries ${retries} is rejected`, async () => await assert.rejects(()=>resolveHealthcheck({Test:['CMD','check'],Retries:retries}),code('REGISTRY_CONFIG_HEALTHCHECK_RETRIES')));
test('changed Healthcheck command changes its projection and selected Config hashes', async () => { const a=(await resolveHealthcheck({Test:['CMD','one']})).result,b=(await resolveHealthcheck({Test:['CMD','two']})).result; assert.notEqual(a.healthcheck.payload_sha256,b.healthcheck.payload_sha256); assert.notEqual(a.selected_config_sha256,b.selected_config_sha256); });
test('changed Healthcheck timing changes its projection and selected Config hashes', async () => { const a=(await resolveHealthcheck({Test:['CMD','check'],Interval:1000000})).result,b=(await resolveHealthcheck({Test:['CMD','check'],Interval:2000000})).result; assert.notEqual(a.healthcheck.projection_sha256,b.healthcheck.projection_sha256); assert.notEqual(a.selected_config_sha256,b.selected_config_sha256); });
test('explicit runtime executable Healthcheck overrides executable image Healthcheck', () => { const c=load(); const out=classifyHealthcheckRuntime({imageHealthcheck:{Test:['CMD','image-check']},runtimeHealthcheck:{Test:['CMD','runtime-check']},policy:c.healthcheck_policy}); assert.equal(out.classification,'B_EXECUTABLE_BUT_OVERRIDDEN_OR_DISABLED'); assert.equal(out.runtime_effect,'OVERRIDDEN'); });
test('explicit runtime NONE disables executable image Healthcheck while retaining inherited timing evidence', () => { const c=load(); const out=classifyHealthcheckRuntime({imageHealthcheck:{Test:['CMD','image-check'],Interval:15000000000},runtimeHealthcheck:{Test:['NONE']},policy:c.healthcheck_policy}); assert.equal(out.classification,'B_EXECUTABLE_BUT_OVERRIDDEN_OR_DISABLED'); assert.equal(out.runtime_effect,'DISABLED'); assert.equal(out.field_sources.Interval,'IMAGE'); assert.deepEqual(out.effective.interval,{present:true,value_nanoseconds:15000000000}); });
test('omitted runtime Healthcheck inherits executable image Healthcheck', () => { const c=load(); const out=classifyHealthcheckRuntime({imageHealthcheck:{Test:['CMD','image-check']},policy:c.healthcheck_policy}); assert.equal(out.classification,'C_EXECUTABLE_AND_INHERITED'); assert.equal(out.runtime_effect,'INHERITED'); });
test('runtime command override still inherits omitted image StartInterval under Moby field merge', () => { const c=load(); const out=classifyHealthcheckRuntime({imageHealthcheck:{Test:['CMD','image-check'],Interval:15000000000,StartInterval:1000000000},runtimeHealthcheck:{Test:['CMD-SHELL','runtime-check'],Interval:10000000000,StartInterval:0},policy:c.healthcheck_policy}); assert.equal(out.classification,'B_EXECUTABLE_BUT_OVERRIDDEN_OR_DISABLED'); assert.equal(out.field_sources.Test,'RUNTIME'); assert.equal(out.field_sources.StartInterval,'IMAGE'); assert.deepEqual(out.effective.start_interval,{present:true,value_nanoseconds:1000000000}); });
test('Healthcheck payload cannot trigger network activity during metadata resolution', async () => { const {calls}=await resolveHealthcheck({Test:['CMD-SHELL','curl https://unapproved.example/']}); assert.equal(calls.length,5); assert.equal(calls.some(call=>call.host==='unapproved.example'),false); });
test('source reference parsing is byte exact', () => assert.deepEqual(parseApprovedSourceReference(load(),'AUTH','supabase/gotrue:v2.195.0'),source()));
