test('Docker manifest list media type is supported', async () => { const a=artifacts({indexType:'application/vnd.docker.distribution.manifest.list.v2+json',manifestType:'application/vnd.docker.distribution.manifest.v2+json'}); assert.equal((await resolveWith(anonymousQueue(a))).result.manifest_media_type,a.index.mediaType); });
test('single manifest is supported when config proves exact platform', async () => { const a=artifacts({configValue:{architecture:'arm64',os:'linux',variant:'v8',config:{}}}); const queue=anonymousQueue(a); queue.splice(2,2,response(a.childBytes,a.child.mediaType)); const {result}=await resolveWith(queue); assert.equal(result.top_level_manifest_digest,result.platform_child_digest); });
test('requested linux arm64 v8 accepts one explicit v8 descriptor', () => { const a=artifacts(); assert.equal(select(a.index).digest,a.childDigest); });
test('requested linux arm64 v8 accepts one descriptor with omitted variant', () => { const a=artifacts(); delete a.index.manifests[0].platform.variant; assert.equal(select(a.index).digest,a.childDigest); });
test('descriptor null variant is not widened into OCI index omission', () => { const a=artifacts(); a.index.manifests[0].platform.variant=null; assert.throws(()=>select(a.index),code('REGISTRY_PLATFORM_MISSING')); });
test('requested linux arm64 v8 rejects incompatible explicit descriptor variant', () => { const a=artifacts(); a.index.manifests[0].platform.variant='v9'; assert.throws(()=>select(a.index),code('REGISTRY_PLATFORM_MISSING')); });
test('linux arm v7 never satisfies requested arm v8', () => assert.equal(platformCompatible({os:'linux',architecture:'arm',variant:'v7'},{os:'linux',architecture:'arm',variant:'v8'}),false));
test('amd64 does not satisfy requested arm64', () => { const a=artifacts(); a.index.manifests[0].platform.architecture='amd64'; assert.throws(()=>select(a.index),code('REGISTRY_PLATFORM_MISSING')); });
test('wrong OS is rejected', () => { const a=artifacts(); a.index.manifests[0].platform.os='windows'; assert.throws(()=>select(a.index),code('REGISTRY_PLATFORM_MISSING')); });
test('zero compatible executable descriptors fails closed', () => { const a=artifacts(); a.index.manifests=[]; assert.throws(()=>select(a.index),code('REGISTRY_PLATFORM_MISSING')); });
test('exactly one compatible descriptor is selected', () => { const a=artifacts(); a.index.manifests.unshift({...clone(a.index.manifests[0]),digest:`sha256:${H('8')}`,platform:{os:'linux',architecture:'amd64'}}); assert.equal(select(a.index).digest,a.childDigest); });
test('multiple compatible descriptors are ambiguous', () => { const a=artifacts(); a.index.manifests.push(clone(a.index.manifests[0])); assert.throws(()=>select(a.index),code('REGISTRY_PLATFORM_AMBIGUOUS')); });
test('explicit v8 plus omitted arm64 candidate coexistence is ambiguous', () => { const a=artifacts(); const omitted=clone(a.index.manifests[0]); delete omitted.platform.variant; omitted.digest=`sha256:${H('7')}`; a.index.manifests.push(omitted); assert.throws(()=>select(a.index),code('REGISTRY_PLATFORM_AMBIGUOUS')); });
test('unknown attestation descriptor is ignored as non-executable', () => { const a=artifacts(); a.index.manifests.unshift({mediaType:a.child.mediaType,size:1,digest:`sha256:${H('6')}`,platform:{os:'unknown',architecture:'unknown'},annotations:{'vnd.docker.reference.type':'attestation-manifest','vnd.docker.reference.digest':a.childDigest}}); const projection=projectIndexPlatformDescriptors(a.index,load()); assert.equal(projection[0].executable_candidate,false); assert.equal(projection[0].classification,'NON_RUNTIME_ATTESTATION'); assert.equal(select(a.index).digest,a.childDigest); });
test('descriptor missing architecture is ignored as non-executable', () => { const a=artifacts(); delete a.index.manifests[0].platform.architecture; assert.throws(()=>select(a.index),code('REGISTRY_PLATFORM_MISSING')); });
test('descriptor missing OS is ignored as non-executable', () => { const a=artifacts(); delete a.index.manifests[0].platform.os; assert.throws(()=>select(a.index),code('REGISTRY_PLATFORM_MISSING')); });
test('config architecture mismatch is rejected', async () => { const a=artifacts({configValue:{architecture:'amd64',os:'linux',config:{}}}); await assert.rejects(()=>resolveWith(anonymousQueue(a)),code('REGISTRY_CONFIG_PLATFORM')); });
test('config OS mismatch is rejected', async () => { const a=artifacts({configValue:{architecture:'arm64',os:'windows',config:{}}}); await assert.rejects(()=>resolveWith(anonymousQueue(a)),code('REGISTRY_CONFIG_PLATFORM')); });
test('config explicit variant mismatch is rejected', async () => { const a=artifacts({configValue:{architecture:'arm64',os:'linux',variant:'v9',config:{}}}); await assert.rejects(()=>resolveWith(anonymousQueue(a)),code('REGISTRY_CONFIG_VARIANT')); });
test('config omitted variant is accepted only by the narrow arm64 v8 rule', async () => { const a=artifacts({configValue:{architecture:'arm64',os:'linux',config:{}}}); assert.deepEqual((await resolveWith(anonymousQueue(a))).result.platform,platform); });
test('config null variant is accepted as OCI-equivalent to omission', async () => { const a=artifacts({configValue:{architecture:'arm64',os:'linux',variant:null,config:{}}}); assert.deepEqual((await resolveWith(anonymousQueue(a))).result.platform,platform); });
test('direct single-platform manifest accepts config with omitted arm64 v8 variant', async () => { const a=artifacts({configValue:{architecture:'arm64',os:'linux',config:{}}}); const queue=anonymousQueue(a); queue.splice(2,2,response(a.childBytes,a.child.mediaType)); const {result}=await resolveWith(queue); assert.equal(result.top_level_manifest_digest,result.platform_child_digest); });
test('selector never chooses the first of ambiguous compatible descriptors', () => { const a=artifacts(); const omitted=clone(a.index.manifests[0]); delete omitted.platform.variant; omitted.digest=`sha256:${H('5')}`; a.index.manifests.unshift(omitted); assert.throws(()=>select(a.index),code('REGISTRY_PLATFORM_AMBIGUOUS')); });
test('selection is deterministic across nonmatching descriptor order', () => { const a=artifacts(); const nonmatching=[{...clone(a.index.manifests[0]),digest:`sha256:${H('3')}`,platform:{os:'linux',architecture:'amd64'}},{...clone(a.index.manifests[0]),digest:`sha256:${H('4')}`,platform:{os:'windows',architecture:'arm64',variant:'v8'}}]; const first={...a.index,manifests:[nonmatching[0],a.index.manifests[0],nonmatching[1]]}; const second={...a.index,manifests:[nonmatching[1],nonmatching[0],a.index.manifests[0]]}; assert.equal(select(first).digest,select(second).digest); });
